(function(root){
function back(tab,wx,current){if(tab!=='wechat'||wx==='moments')return null;return current||wx!=='chat'?{tab:'wechat',wxTab:'chat',current:null}:{tab:'home',wxTab:'chat',current:null}}
function crop(w,h,zoom,x,y,side=280){const scale=Math.max(side/w,side/h)*Math.max(1,Math.min(4,zoom)),mx=(w*scale-side)/2,my=(h*scale-side)/2;return {scale,x:Math.max(-mx,Math.min(mx,x)),y:Math.max(-my,Math.min(my,y)),size:side/scale}}
function dissolve(state,id,keep,at){const s=JSON.parse(JSON.stringify(state)),g=s.groups.find(x=>x.id===id);if(!g)throw Error('群聊已解散');const history=s.histories[id]||[];s.dissolved=s.dissolved||{};if(keep){s.dissolved[id]={...g,closedAt:at,history:history.map(m=>({...m,audience:m.audience||g.members})),pending:g.members.slice()}}else{delete s.dissolved[id];delete s.memories[id];for(const who of g.members){const key='shared:'+who,m=s.memories[key];if(m)s.memories[key]={pinned:m.pinned||'',summary:'',processed:0,archives:[],revision:(m.revision||0)+1}}}s.groups=s.groups.filter(g=>g.id!==id);delete s.histories[id];s.notices=s.notices.filter(n=>n.conversationId!==id);s.wx18.drafts={...s.wx18.drafts};delete s.wx18.drafts[id];s.wx18.prefs={...s.wx18.prefs};delete s.wx18.prefs[id];return s}
const api={back,crop,dissolve};root.Fix25=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
